// Idempotency: remove any previously injected carousel first
const existing = document.getElementById('__sponsored_carousel__');
if (existing) existing.remove();

// Gather all sponsored ad list items in the results
const adItems = element.querySelectorAll('li.b_ad');
if (!adItems || adItems.length === 0) return;

// ── Build the carousel wrapper ──────────────────────────────────────────────
const carousel = document.createElement('div');
carousel.id = '__sponsored_carousel__';
carousel.style.cssText = [
  'width: 100%',
  'box-sizing: border-box',
  'background: linear-gradient(135deg, #fff8e1 0%, #fff3cd 60%, #ffeaa7 100%)',
  'border: 2.5px solid #f39c12',
  'border-radius: 14px',
  'padding: 18px 20px 14px',
  'margin-bottom: 22px',
  'box-shadow: 0 4px 20px rgba(243,156,18,0.22), 0 1px 6px rgba(0,0,0,0.08)',
  'position: relative',
  'z-index: 10',
  'font-family: "Segoe UI", Arial, sans-serif'
].join(';');

// ── Header row ───────────────────────────────────────────────────────────────
const header = document.createElement('div');
header.style.cssText = [
  'display: flex',
  'align-items: center',
  'gap: 8px',
  'margin-bottom: 14px'
].join(';');

const badge = document.createElement('span');
badge.textContent = '🛒 Sponsored Product Deals';
badge.style.cssText = [
  'background: #f39c12',
  'color: #fff',
  'font-weight: 700',
  'font-size: 13px',
  'padding: 4px 12px',
  'border-radius: 20px',
  'letter-spacing: 0.4px',
  'text-transform: uppercase'
].join(';');

const subLabel = document.createElement('span');
subLabel.textContent = 'Purchase options — instantly at the top';
subLabel.style.cssText = 'color: #7b5e00; font-size: 12px; font-style: italic;';

header.appendChild(badge);
header.appendChild(subLabel);
carousel.appendChild(header);

// ── Scrollable track ─────────────────────────────────────────────────────────
const trackWrapper = document.createElement('div');
trackWrapper.style.cssText = [
  'position: relative'
].join(';');

const track = document.createElement('div');
track.id = '__spc_track__';
track.style.cssText = [
  'display: flex',
  'gap: 16px',
  'overflow-x: auto',
  'scroll-behavior: smooth',
  'padding-bottom: 8px',
  'scrollbar-width: thin',
  'scrollbar-color: #f39c12 #ffeaa7'
].join(';');

// ── Render each ad as a card ──────────────────────────────────────────────────
adItems.forEach(function(ad) {
  const card = document.createElement('div');
  card.style.cssText = [
    'flex: 0 0 280px',
    'background: #ffffff',
    'border: 1.5px solid #f0c060',
    'border-radius: 10px',
    'padding: 14px 16px',
    'box-shadow: 0 2px 8px rgba(0,0,0,0.08)',
    'display: flex',
    'flex-direction: column',
    'gap: 8px',
    'position: relative',
    'overflow: hidden'
  ].join(';');

  // Sponsored pill
  const pill = document.createElement('span');
  pill.textContent = 'Sponsored';
  pill.style.cssText = [
    'position: absolute',
    'top: 10px',
    'right: 10px',
    'background: #fff3cd',
    'color: #856404',
    'font-size: 10px',
    'font-weight: 600',
    'padding: 2px 8px',
    'border-radius: 10px',
    'border: 1px solid #ffc107',
    'text-transform: uppercase',
    'letter-spacing: 0.3px'
  ].join(';');
  card.appendChild(pill);

  // Domain / site
  const domainEl = ad.querySelector('.b_domian');
  if (domainEl) {
    const site = document.createElement('div');
    site.style.cssText = 'font-size: 11px; color: #006621; font-weight: 600; margin-top: 2px;';
    site.textContent = (domainEl.textContent || '').trim();
    card.appendChild(site);
  }

  // Title link
  const titleAnchor = ad.querySelector('h2 a');
  if (titleAnchor) {
    const titleLink = document.createElement('a');
    titleLink.href = titleAnchor.href || '#';
    titleLink.target = '_blank';
    titleLink.rel = 'noopener noreferrer';
    titleLink.textContent = (titleAnchor.textContent || '').trim();
    titleLink.style.cssText = [
      'font-size: 14px',
      'font-weight: 700',
      'color: #1a0dab',
      'text-decoration: none',
      'line-height: 1.35',
      'display: -webkit-box',
      '-webkit-line-clamp: 2',
      '-webkit-box-orient: vertical',
      'overflow: hidden'
    ].join(';');
    titleLink.onmouseover = function() { this.style.textDecoration = 'underline'; };
    titleLink.onmouseout  = function() { this.style.textDecoration = 'none'; };
    card.appendChild(titleLink);
  }

  // Description
  const descEl = ad.querySelector('.b_ad_description');
  if (descEl) {
    const desc = document.createElement('p');
    const rawText = (descEl.innerText || descEl.textContent || '').replace(/Sponsored/gi, '').trim();
    desc.textContent = rawText;
    desc.style.cssText = [
      'font-size: 12px',
      'color: #444',
      'margin: 0',
      'line-height: 1.5',
      'display: -webkit-box',
      '-webkit-line-clamp: 3',
      '-webkit-box-orient: vertical',
      'overflow: hidden'
    ].join(';');
    card.appendChild(desc);
  }

  // Callout badges
  const calloutEl = ad.querySelector('.callout_vis');
  if (calloutEl) {
    const calloutText = (calloutEl.textContent || '').trim();
    if (calloutText) {
      const calloutRow = document.createElement('div');
      calloutRow.style.cssText = 'display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px;';
      calloutText.split('·').forEach(function(chunk) {
        const chunkTrim = chunk.trim();
        if (!chunkTrim) return;
        const tag = document.createElement('span');
        tag.textContent = chunkTrim;
        tag.style.cssText = [
          'background: #e8f5e9',
          'color: #2e7d32',
          'font-size: 10px',
          'font-weight: 600',
          'padding: 2px 7px',
          'border-radius: 8px',
          'border: 1px solid #a5d6a7'
        ].join(';');
        calloutRow.appendChild(tag);
      });
      card.appendChild(calloutRow);
    }
  }

  // URL cite
  const citeEl = ad.querySelector('cite');
  if (citeEl) {
    const citeDiv = document.createElement('div');
    citeDiv.textContent = (citeEl.textContent || '').trim();
    citeDiv.style.cssText = 'font-size: 10.5px; color: #006621; margin-top: 4px; word-break: break-all;';
    card.appendChild(citeDiv);
  }

  // "Shop Now" CTA button
  const anchor = ad.querySelector('h2 a');
  if (anchor) {
    const cta = document.createElement('a');
    cta.href = anchor.href || '#';
    cta.target = '_blank';
    cta.rel = 'noopener noreferrer';
    cta.textContent = '🛍️ Shop Now';
    cta.style.cssText = [
      'display: inline-block',
      'margin-top: auto',
      'padding: 7px 14px',
      'background: linear-gradient(135deg, #f39c12, #e67e22)',
      'color: #fff',
      'font-size: 12px',
      'font-weight: 700',
      'border-radius: 20px',
      'text-decoration: none',
      'text-align: center',
      'letter-spacing: 0.3px',
      'box-shadow: 0 2px 6px rgba(230,126,34,0.35)',
      'transition: opacity 0.15s'
    ].join(';');
    cta.onmouseover = function() { this.style.opacity = '0.85'; };
    cta.onmouseout  = function() { this.style.opacity = '1'; };
    card.appendChild(cta);
  }

  track.appendChild(card);
});

trackWrapper.appendChild(track);

// ── Scroll arrow buttons ──────────────────────────────────────────────────────
function makeArrow(dir) {
  const btn = document.createElement('button');
  btn.textContent = dir === 'left' ? '‹' : '›';
  btn.style.cssText = [
    'position: absolute',
    'top: 50%',
    'transform: translateY(-50%)',
    dir === 'left' ? 'left: -16px' : 'right: -16px',
    'z-index: 5',
    'width: 32px',
    'height: 32px',
    'border-radius: 50%',
    'border: 2px solid #f39c12',
    'background: #fff',
    'color: #f39c12',
    'font-size: 22px',
    'line-height: 1',
    'cursor: pointer',
    'box-shadow: 0 2px 8px rgba(0,0,0,0.15)',
    'display: flex',
    'align-items: center',
    'justify-content: center',
    'padding: 0',
    'font-weight: 700'
  ].join(';');
  btn.onclick = function() {
    const t = document.getElementById('__spc_track__');
    if (t) t.scrollLeft += dir === 'left' ? -300 : 300;
  };
  return btn;
}

trackWrapper.appendChild(makeArrow('left'));
trackWrapper.appendChild(makeArrow('right'));
carousel.appendChild(trackWrapper);

// ── Footer note ───────────────────────────────────────────────────────────────
const footer = document.createElement('div');
footer.textContent = '✦ Deals sourced from sponsored listings on this page';
footer.style.cssText = 'font-size: 10.5px; color: #a07820; margin-top: 10px; text-align: right;';
carousel.appendChild(footer);

// ── Insert at very top of results list ───────────────────────────────────────
element.insertBefore(carousel, element.firstChild);
